print("=== 关键词搜索结果 ===\n")
for kw in keywords:
    if kw.upper() in content.upper():
        # Find lines containing this keyword
        for line in content.split('\n'):
            if kw.upper() in line.upper():
                print(f"  [{kw}] {line.strip()}")
    else:
        print(f"  [{kw}] 未找到")

